import{_ as r,K as s,a as l,c as n,ac as t,b as e,q as o}from"./chunks/framework.BSuaGltH.js";const b=JSON.parse('{"title":"围棋：从布局到收官的一盘棋复盘","description":"用一个九路练习的分阶段检查和计分例子，找到失误原因，而不是只数提子。","frontmatter":{"title":"围棋：从布局到收官的一盘棋复盘","description":"用一个九路练习的分阶段检查和计分例子，找到失误原因，而不是只数提子。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"棋类入门","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"围棋入门","summary":"用一个九路练习的分阶段检查和计分例子，找到失误原因，而不是只数提子。","status":"active","related":[{"title":"围棋：落子、气、提子与胜负计算","link":"/life/personal/chess/weiqi/rules","kind":"棋类入门","scope":"general","audience":"general"},{"title":"围棋：连接、断点与基本吃子技巧","link":"/life/personal/chess/weiqi/connections","kind":"棋类入门","scope":"general","audience":"general"},{"title":"围棋：眼、死活与简单对杀","link":"/life/personal/chess/weiqi/life-death","kind":"棋类入门","scope":"general","audience":"general"}],"prev":{"text":"围棋：眼、死活与简单对杀","link":"/life/personal/chess/weiqi/life-death"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"围棋：眼、死活与简单对杀","link":"/life/personal/chess/weiqi/life-death"},"next":false},"headers":[],"relativePath":"life/personal/chess/weiqi/review.md","filePath":"life/personal/chess/weiqi/review.md"}'),d={name:"life/personal/chess/weiqi/review.md"},c={class:"chess-example"},p={class:"chess-figure"};function h(f,a,_,u,g,m){const i=s("ArticleImage");return l(),n("div",null,[a[1]||(a[1]=t('<h1 id="围棋-从布局到收官的一盘棋复盘" tabindex="-1">围棋：从布局到收官的一盘棋复盘 <a class="header-anchor" href="#围棋-从布局到收官的一盘棋复盘" aria-label="Permalink to &quot;围棋：从布局到收官的一盘棋复盘&quot;">​</a></h1><p>围棋复盘先看哪里丢了整块棋，再看边界损失，最后才研究第一步是否下在“最佳点”。这里用原创九路练习片段说明过程，不把片段冒充完整职业棋谱。</p><h2 id="布局-给棋子留出发展空间" tabindex="-1">布局：给棋子留出发展空间 <a class="header-anchor" href="#布局-给棋子留出发展空间" aria-label="Permalink to &quot;布局：给棋子留出发展空间&quot;">​</a></h2><p>棋盘刚开始很空，先占角或边通常较容易围出区域，因为棋盘边界可以帮忙。中央棋也有价值，但一颗中央孤子并不会自动围住整片中央。</p><p>在 9 路棋盘上依次摆黑 C3、白 G7、黑 G3、白 C7。本文列 A～I，不跳字母。这四步只是说明双方分占不同方向。现在轮黑，考虑一个问题：是补强已有棋，还是向另一处扩张？没有接触战时可以想大一些；一旦有棋串只剩一口气，就必须先处理局部危险。</p><h2 id="中盘-先找第一处可避免的损失" tabindex="-1">中盘：先找第一处可避免的损失 <a class="header-anchor" href="#中盘-先找第一处可避免的损失" aria-label="Permalink to &quot;中盘：先找第一处可避免的损失&quot;">​</a></h2>',6)),e("div",c,[e("div",p,[e("p",null,[o(i,{src:"/images/chess/weiqi-review.svg",alt:"脱先之前 · 先看最后一气。黑走；B2 只剩 B3 一气，应先检查局部。"})])]),a[0]||(a[0]=e("div",{class:"chess-explanation"},[e("p",null,"复盘到一串棋被提时，不要从“提走的那一步”才开始看，向前退两三手。"),e("p",null,"例如局部黑 B2，白 A2、B1、C2，轮黑。黑为了占远处一个点，下到 H8；白下 B3，黑 B2 被提。真正的问题在黑选择 H8 的那一刻：它忽略了 B2 只有一口气。改下 B3，可使黑串获得 A3、C3、B4 三口气（假设这些点空着），这是可以在棋盘上验证的替代方案。"),e("p",null,"不要写“以后不能脱先”。脱先就是暂时去别处下，有时正确。这里应写“脱先前检查所有只剩一气的棋串”，这样规则更具体。")],-1))]),a[2]||(a[2]=t('<h2 id="收官-边界小变化也要算" tabindex="-1">收官：边界小变化也要算 <a class="header-anchor" href="#收官-边界小变化也要算" aria-label="Permalink to &quot;收官：边界小变化也要算&quot;">​</a></h2><p>大块死活安定后，双方继续争夺区域边界，这叫收官。有的收官要求对手立刻应对，有的走完对手可以去别处；先后手价值不同。</p><p>在练习计分时，假设一个边界点原本属于白方，黑通过合法变化把它变成黑方控制：黑加一、白减一，双方差距变化两点。<strong>“我多一”和“分差变两”是不同说法。</strong> 这个算术例子不表示任何边界点都可以直接侵入，要先证明变化后棋能活、边界成立。</p><h2 id="终局-把账对上" tabindex="-1">终局：把账对上 <a class="header-anchor" href="#终局-把账对上" aria-label="Permalink to &quot;终局：把账对上&quot;">​</a></h2><p>继续使用面积计分的课堂约定。终局黑活子加空点合计 40，白合计 39，中立点 2，合计 81。若约定白贴 6.5，白为 45.5，白胜 5.5 点。提子数量不额外相加。</p><p>若双方对一块棋是否死有分歧，不要一边坚持“明显死”一边从棋盘拿走。保留局面，按约定规则继续验证或请求裁定。数目法与面积法也不要在结算时临时混用。</p><h2 id="一份可以直接照着写的复盘" tabindex="-1">一份可以直接照着写的复盘 <a class="header-anchor" href="#一份可以直接照着写的复盘" aria-label="Permalink to &quot;一份可以直接照着写的复盘&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>本次填写例子</th></tr></thead><tbody><tr><td>局面</td><td>黑 B2 被白三面包围，黑走</td></tr><tr><td>当时想法</td><td>H8 地方很大，先占一个点</td></tr><tr><td>漏看信息</td><td>B2 只剩 B3 一口气</td></tr><tr><td>替代方案</td><td>黑 B3，重新数出三口气</td></tr><tr><td>下一盘目标</td><td>每次脱先前扫描一气棋</td></tr></tbody></table><p>每盘只留一个主要改进点。连续三盘都能记得检查后，再加第二个习惯。</p><h2 id="练习与答案" tabindex="-1">练习与答案 <a class="header-anchor" href="#练习与答案" aria-label="Permalink to &quot;练习与答案&quot;">​</a></h2><ol><li>黑 41、白 38、中立 2，白贴 6.5，谁赢？<strong>白 44.5 对黑 41，白胜 3.5。</strong></li><li>吃了对方十颗子却输了，是否规则出错？<strong>未必。</strong> 对方可能围得更多，吃子数不是最终分数。</li><li>第一次复盘应该研究布局细节还是漏提整块？<strong>先解决可以明确验证的整块损失。</strong></li></ol><p>计分口径参考：<a href="https://www.usgo-archive.org/files/pdf/conciserules.pdf" target="_blank" rel="noopener noreferrer">AGA 简明规则</a>。本篇布局片段、局部变化和数字为独立练习，不是一盘完整对局的连续记录。</p>',12))])}const k=r(d,[["render",h]]);export{b as __pageData,k as default};
